/**
 * ConnectionErrorToast - Toast notification for voice agent connection errors
 *
 * Features:
 * - Appears on connection error with diagnostic information
 * - Auto-dismisses after 10 seconds with countdown
 * - Manual dismiss button
 * - Retry action button
 * - Actionable solutions with links
 * - Respects reduced-motion preferences
 * - Accessible with proper ARIA labels
 *
 * Design follows neumorphic patterns from the codebase
 *
 * @component
 * @see {@link ./docs/VOICE_AGENT_GUIDE.md} for integration documentation
 *
 * @example Basic usage
 * ```tsx
 * import { useVoiceAgent } from '@/context/VoiceAgentContext';
 * import ConnectionErrorToast from '@/components/features/ConnectionErrorToast';
 *
 * function App() {
 *   const voiceAgent = useVoiceAgent();
 *   const [showToast, setShowToast] = useState(false);
 *
 *   useEffect(() => {
 *     // Show toast when error occurs
 *     if (voiceAgent.connectionState === 'error' && voiceAgent.errorMessage) {
 *       setShowToast(true);
 *     }
 *     // Auto-dismiss when connection succeeds
 *     else if (voiceAgent.connectionState === 'connected') {
 *       setShowToast(false);
 *     }
 *   }, [voiceAgent.connectionState, voiceAgent.errorMessage]);
 *
 *   return (
 *     <>
 *       <ConnectionErrorToast
 *         isVisible={showToast}
 *         errorMessage={voiceAgent.errorMessage || ''}
 *         onRetry={() => voiceAgent.retry()}
 *         onDismiss={() => setShowToast(false)}
 *         onOpenSettings={() => setIsSettingsOpen(true)}
 *       />
 *     </>
 *   );
 * }
 * ```
 */

import React, { useEffect, useState, useCallback, useMemo } from 'react';
import { prefersReducedMotion } from '@/utils/haptics';
import { diagnoseVoiceError, getErrorCode } from '@/utils/voiceErrorDiagnostics';

/**
 * Props for ConnectionErrorToast component
 *
 * @interface ConnectionErrorToastProps
 */
interface ConnectionErrorToastProps {
  /** Whether the toast is visible */
  isVisible: boolean;
  /** Error message to display (from VoiceAgentContext.errorMessage) */
  errorMessage: string;
  /** Optional error code (e.g., "401", "429") */
  errorCode?: string;
  /** Callback when retry button is clicked (call voiceAgent.retry()) */
  onRetry: () => void;
  /** Callback when dismiss button is clicked or auto-dismiss triggers */
  onDismiss: () => void;
  /** Callback to open settings modal (for API key errors) */
  onOpenSettings?: () => void;
  /** Auto-dismiss duration in milliseconds (default: 10000ms / 10 seconds) */
  autoDismissMs?: number;
}

const ConnectionErrorToast: React.FC<ConnectionErrorToastProps> = ({
  isVisible,
  errorMessage,
  errorCode,
  onRetry,
  onDismiss,
  onOpenSettings,
  autoDismissMs = 10000,
}) => {
  const [countdown, setCountdown] = useState(Math.ceil(autoDismissMs / 1000));
  const [isAnimatingOut, setIsAnimatingOut] = useState(false);

  // Memoize reducedMotion check to prevent recalculation on every render
  const reducedMotion = useMemo(() => prefersReducedMotion(), []);

  // Diagnose the error to get helpful information
  const diagnostic = useMemo(() => {
    const code = errorCode || getErrorCode(errorMessage);
    return diagnoseVoiceError(errorMessage, code);
  }, [errorMessage, errorCode]);

  // Reset countdown when toast becomes visible
  useEffect(() => {
    if (isVisible) {
      setCountdown(Math.ceil(autoDismissMs / 1000));
      setIsAnimatingOut(false);
    }
  }, [isVisible, autoDismissMs]);

  // Handle dismiss with animation
  const handleDismiss = useCallback(() => {
    if (reducedMotion) {
      // Skip animation if user prefers reduced motion
      onDismiss();
    } else {
      // Trigger exit animation
      setIsAnimatingOut(true);
      // Wait for animation to complete before calling onDismiss
      setTimeout(() => {
        onDismiss();
      }, 300); // Match animation duration
    }
  }, [onDismiss, reducedMotion]);

  // Auto-dismiss timer with countdown
  useEffect(() => {
    if (!isVisible) return;

    const countdownInterval = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          clearInterval(countdownInterval);
          handleDismiss();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(countdownInterval);
  }, [isVisible, handleDismiss]);

  // Handle retry button click
  const handleRetry = useCallback(() => {
    handleDismiss(); // Dismiss toast
    onRetry(); // Trigger retry
  }, [handleDismiss, onRetry]);

  // Handle action link click
  const handleActionClick = useCallback(() => {
    if (!diagnostic.actionLink) return;

    if (diagnostic.actionLink.opensSettings && onOpenSettings) {
      // Open settings modal
      onOpenSettings();
    } else if (diagnostic.actionLink.url) {
      // Open external link
      window.open(diagnostic.actionLink.url, '_blank', 'noopener,noreferrer');
    }
  }, [diagnostic.actionLink, onOpenSettings]);

  // Don't render if not visible
  if (!isVisible && !isAnimatingOut) return null;

  // Animation classes based on reduced motion preference
  const animationClasses = reducedMotion
    ? ''
    : isAnimatingOut
    ? 'animate-slide-out-right opacity-0'
    : 'animate-slide-in-right';

  return (
    <div
      role="alert"
      aria-live="assertive"
      aria-atomic="true"
      className={`fixed top-20 right-4 z-50 max-w-md w-full ${animationClasses}`}
    >
      {/* Toast Container - Neumorphic design with red error theme */}
      <div className="bg-zinc-900 border border-red-500/30 rounded-lg shadow-lg shadow-red-500/20 overflow-hidden">
        {/* Header with error icon and title */}
        <div className="flex items-start gap-3 p-4 pb-3 border-b border-red-500/20 bg-red-950/20">
          <span className="material-icons text-red-500 text-2xl flex-shrink-0">
            error_outline
          </span>
          <div className="flex-1 min-w-0">
            <h3 className="text-red-400 font-semibold text-sm uppercase tracking-wider">
              {diagnostic.title}
            </h3>
            {errorCode && (
              <p className="text-red-500/70 text-xs mt-1">
                Error Code: {errorCode}
              </p>
            )}
          </div>
          {/* Manual dismiss button */}
          <button
            onClick={handleDismiss}
            className="flex-shrink-0 text-zinc-400 hover:text-zinc-200 transition-colors"
            aria-label="Dismiss error notification"
          >
            <span className="material-icons text-xl">close</span>
          </button>
        </div>

        {/* Error description and solution */}
        <div className="p-4 pt-3 space-y-3">
          {/* Description */}
          <p className="text-zinc-300 text-sm leading-relaxed">
            {diagnostic.description}
          </p>

          {/* Solution */}
          <div className="flex gap-2">
            <span className="material-icons text-blue-400 text-sm mt-0.5 flex-shrink-0">
              lightbulb
            </span>
            <p className="text-zinc-400 text-sm leading-relaxed">
              {diagnostic.solution}
            </p>
          </div>

          {/* Action link (if available) */}
          {diagnostic.actionLink && (
            <div className="pt-2">
              <button
                onClick={handleActionClick}
                className="inline-flex items-center gap-1.5 text-blue-400 hover:text-blue-300 text-sm font-medium transition-colors underline-offset-2 hover:underline"
                aria-label={diagnostic.actionLink.text}
              >
                <span className="material-icons text-sm">
                  {diagnostic.actionLink.opensSettings ? 'settings' : 'open_in_new'}
                </span>
                {diagnostic.actionLink.text}
              </button>
            </div>
          )}
        </div>

        {/* Action buttons and countdown */}
        <div className="flex items-center justify-between gap-3 p-4 pt-0 pb-3">
          {/* Retry button (only show if error is retryable) */}
          {diagnostic.retryable && (
            <button
              onClick={handleRetry}
              className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-500 text-white text-xs font-semibold uppercase tracking-wider rounded transition-colors"
              aria-label="Retry connection"
            >
              <span className="material-icons text-sm">refresh</span>
              Retry
            </button>
          )}

          {/* Auto-dismiss countdown */}
          <div className={`flex items-center gap-2 text-zinc-500 text-xs ${diagnostic.retryable ? '' : 'ml-auto'}`}>
            <span className="material-icons text-sm">schedule</span>
            <span aria-live="polite" aria-atomic="true">
              Dismissing in {countdown}s
            </span>
          </div>
        </div>

        {/* Progress bar showing time remaining */}
        <div className="h-1 bg-zinc-800 overflow-hidden">
          <div
            className="h-full bg-red-500 transition-all ease-linear"
            style={{
              width: `${(countdown / (autoDismissMs / 1000)) * 100}%`,
              transitionDuration: reducedMotion ? '0s' : '1s',
            }}
            role="progressbar"
            aria-valuemin={0}
            aria-valuemax={autoDismissMs / 1000}
            aria-valuenow={countdown}
            aria-label="Time remaining before auto-dismiss"
          />
        </div>
      </div>
    </div>
  );
};

export default ConnectionErrorToast;
